//! The post entity of the `posts` resource, generated by
//! `forge generate scaffold`. Business rules only: no HTTP, SQL or runtime
//! types, so the rules are unit-testable and shared by every adapter.

use std::fmt;

use forge::core::{Id, Version};

/// Identifier of a [`Post`]: a typed UUIDv7 generated in Rust, never by
/// the database.
pub type PostId = Id<Post>;

/// Maximum length, in characters, of a `string` field.
pub const STRING_MAX_CHARS: usize = 255;

/// Maximum length, in characters, of a `text` field.
pub const TEXT_MAX_CHARS: usize = 65_535;

/// The values a post is made of. [`Post`] only holds values that pass
/// [`PostAttributes::validate`].
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct PostAttributes {
    pub title: String,
    pub body: String,
    pub published: bool,
}

impl PostAttributes {
    /// Checks every business rule and reports all violations at once.
    pub fn validate(&self) -> Result<(), PostValidationErrors> {
        let mut errors = PostValidationErrors::default();
        check_text(&mut errors, PostField::Title, &self.title, STRING_MAX_CHARS);
        check_text(&mut errors, PostField::Body, &self.body, TEXT_MAX_CHARS);
        errors.into_result()
    }
}

/// Text must not be blank and must fit `max` characters.
fn check_text(errors: &mut PostValidationErrors, field: PostField, value: &str, max: usize) {
    if value.trim().is_empty() {
        errors.push(field, PostViolation::Blank);
    } else if value.chars().count() > max {
        errors.push(field, PostViolation::TooLong { max });
    }
}

/// A post: an identity, an optimistic-locking version and valid
/// attributes.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct Post {
    id: PostId,
    version: Version,
    attributes: PostAttributes,
}

impl Post {
    /// A new post with a fresh UUIDv7 and the initial version.
    pub fn new(attributes: PostAttributes) -> Result<Self, PostValidationErrors> {
        Self::restore(PostId::new(), Version::INITIAL, attributes)
    }

    /// A post read from storage or about to replace a stored one,
    /// validated like a new one.
    pub fn restore(
        id: PostId,
        version: Version,
        attributes: PostAttributes,
    ) -> Result<Self, PostValidationErrors> {
        attributes.validate()?;
        Ok(Self {
            id,
            version,
            attributes,
        })
    }

    /// The same post at `version`, after storage accepted a change.
    #[must_use]
    pub fn with_version(self, version: Version) -> Self {
        Self { version, ..self }
    }

    #[must_use]
    pub fn id(&self) -> PostId {
        self.id
    }

    /// The optimistic-locking version: an update or delete must present it.
    #[must_use]
    pub fn version(&self) -> Version {
        self.version
    }

    #[must_use]
    pub fn attributes(&self) -> &PostAttributes {
        &self.attributes
    }

    #[must_use]
    pub fn title(&self) -> &str {
        &self.attributes.title
    }

    #[must_use]
    pub fn body(&self) -> &str {
        &self.attributes.body
    }

    #[must_use]
    pub fn published(&self) -> bool {
        self.attributes.published
    }
}

/// A field of [`PostAttributes`].
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum PostField {
    Title,
    Body,
    Published,
}

impl PostField {
    /// The field's name in forms and storage.
    #[must_use]
    pub const fn name(self) -> &'static str {
        match self {
            Self::Title => "title",
            Self::Body => "body",
            Self::Published => "published",
        }
    }
}

/// A broken business rule.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum PostViolation {
    /// The value is empty or only whitespace.
    Blank,
    /// The value has more than `max` characters.
    TooLong { max: usize },
}

impl fmt::Display for PostViolation {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Blank => formatter.write_str("can't be blank"),
            Self::TooLong { max } => write!(formatter, "is too long (at most {max} characters)"),
        }
    }
}

/// Every broken rule of a post, in field order.
#[derive(Clone, Debug, Default, Eq, PartialEq)]
pub struct PostValidationErrors {
    violations: Vec<(PostField, PostViolation)>,
}

impl PostValidationErrors {
    /// Records that `field` breaks a rule.
    pub fn push(&mut self, field: PostField, violation: PostViolation) {
        self.violations.push((field, violation));
    }

    /// Whether no rule is broken.
    #[must_use]
    pub fn is_empty(&self) -> bool {
        self.violations.is_empty()
    }

    /// The first violation of `field`.
    #[must_use]
    pub fn get(&self, field: PostField) -> Option<PostViolation> {
        self.violations
            .iter()
            .find(|(candidate, _)| *candidate == field)
            .map(|(_, violation)| *violation)
    }

    /// Every violation in the order it was found.
    pub fn iter(&self) -> impl Iterator<Item = (PostField, PostViolation)> + '_ {
        self.violations.iter().copied()
    }

    /// `Ok` when no rule is broken.
    pub fn into_result(self) -> Result<(), Self> {
        if self.is_empty() { Ok(()) } else { Err(self) }
    }
}

impl fmt::Display for PostValidationErrors {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter.write_str("post is invalid")?;
        for (index, (field, violation)) in self.violations.iter().enumerate() {
            let separator = if index == 0 { ": " } else { ", " };
            write!(formatter, "{separator}{} {violation}", field.name())?;
        }
        Ok(())
    }
}

impl std::error::Error for PostValidationErrors {}

#[cfg(test)]
mod tests {
    use super::*;

    fn valid() -> PostAttributes {
        PostAttributes {
            title: "Example title".to_owned(),
            body: "Example body".to_owned(),
            published: true,
        }
    }

    #[test]
    fn new_posts_get_a_uuidv7_and_the_initial_version() {
        let created = Post::new(valid());

        let Ok(entity) = created else {
            panic!("valid attributes must be accepted: {created:?}");
        };
        assert_eq!(entity.id().as_uuid().get_version_num(), 7);
        assert_eq!(entity.version(), Version::INITIAL);
        assert_eq!(entity.attributes(), &valid());
    }

    #[test]
    fn blank_and_too_long_text_is_rejected_with_every_violation() {
        let mut attributes = valid();
        attributes.title = "x".repeat(STRING_MAX_CHARS + 1);
        attributes.body = " ".to_owned();

        let Err(errors) = Post::new(attributes) else {
            panic!("blank and too long values must be rejected");
        };
        assert_eq!(
            errors.get(PostField::Title),
            Some(PostViolation::TooLong {
                max: STRING_MAX_CHARS
            })
        );
        assert_eq!(errors.get(PostField::Body), Some(PostViolation::Blank));
    }

    #[test]
    fn restore_validates_and_with_version_keeps_the_identity() -> Result<(), PostValidationErrors> {
        let entity = Post::new(valid())?;
        let restored = Post::restore(entity.id(), entity.version(), valid())?;
        assert_eq!(restored, entity);

        let Ok(next) = Version::INITIAL.next() else {
            panic!("version 2 exists");
        };
        let moved = restored.with_version(next);
        assert_eq!(moved.id(), entity.id());
        assert_eq!(moved.version().get(), 2);
        Ok(())
    }
}
